export function DashboardShell(props: DashboardShellProps) {
  const { org, actor, flags, projects, unreadCount, lockReason, pathname, panel, children } =
    props;

  const flagContext = buildFlagContext(actor, org);

  const mayCreateProject = can(actor, "project:create", {
    kind: "project",
    orgId: org.id,
    projectId: "" as Project["id"],
    visibility: "org",
    leadId: actor.userId,
  });

  const searchEnabled = isEnabled("command_palette", flagContext);

  return (
    <div className="flex min-h-screen">
      <AppSidebar
        org={org}
        actor={actor}
        flags={flags}
        projects={projects}
        pathname={pathname}
      />

      <div className="flex min-w-0 flex-1 flex-col">
        <TopBar org={org} actor={actor} unreadCount={unreadCount} flags={flags} />

        {lockReason !== null ? (
          <div role="status" className="border-b border-amber-300 bg-amber-50 px-6 py-3 text-sm text-amber-950">
            This workspace is read-only because its subscription is {lockReason.replace("_", " ")}.
            Update billing to restore write access.
          </div>
        ) : null}

        <div className="flex items-center gap-4 border-b border-slate-200 bg-white px-6 py-2 text-sm">
          {searchEnabled ? (
            <Link href={`/${org.slug}/search`} className="text-slate-600">
              Search
            </Link>
          ) : null}
          {mayCreateProject ? (
            <Link
              href={`/${org.slug}/projects/new`}
              className="ml-auto rounded-md bg-indigo-600 px-3 py-1.5 font-medium text-white"
            >
              New project
            </Link>
          ) : null}
        </div>

        <div className="flex min-h-0 flex-1">
          <main className="min-w-0 flex-1 px-6 py-8">{children}</main>
          {panel !== undefined ? (
            <aside className="hidden w-80 shrink-0 border-l border-slate-200 bg-white xl:block">
              {panel}
            </aside>
          ) : null}
        </div>
      </div>
    </div>
  );
}
